# General Knowledge and General Awareness: geography (India and its
# neighbours), the economic scene, and everyday science and scientific
# research, as listed in para 12.9.1.2 of the SSC CPO 2026 notice. Static
# facts only: no current affairs, budgets or office-holders.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Rivers", "Dudhsagar Falls, on the Goa and Karnataka border, are on which river?",
      ["Mandovi", "Zuari", "Kaveri", "Sharavati"],
      "Dudhsagar Falls are on the Mandovi in the Western Ghats. Jog Falls are on the Sharavati."),
    S(1, 2, "Vegetation", "The Sundarbans mangrove forest is named after which tree that grows there?",
      ["Sundari", "Sal", "Teak", "Deodar"],
      "The Sundarbans take their name from the sundari, a mangrove tree common in the delta. Sal and teak are trees of the tropical deciduous forests and deodar of the Himalayas."),
    S(1, 3, "Economy", "In government finance, what does the fiscal deficit measure?",
      ["Spending minus non-debt receipts", "Imports minus exports", "Revenue spending minus revenue receipts", "Interest paid on past loans"],
      "The fiscal deficit is total expenditure minus total receipts other than borrowings, so it shows how much the government must borrow. Revenue spending minus revenue receipts is the revenue deficit."),
    S(1, 1, "Biology", "Which instrument measures the amount of glucose in a drop of blood?",
      ["Glucometer", "Sphygmomanometer", "Spirometer", "Stethoscope"],
      "A glucometer reads blood sugar from a drop of blood on a test strip. A sphygmomanometer measures blood pressure, a spirometer the volume of air breathed, and a stethoscope is for listening to the heart and lungs."),
    S(1, 2, "Chemistry", "Calcium carbide, illegally used to ripen fruit, gives off which gas when it reacts with moisture?",
      ["Acetylene", "Ethylene", "Methane", "Ammonia"],
      "Calcium carbide and water produce acetylene (ethyne), which acts like the natural ripening hormone ethylene. Ethylene itself is the gas permitted for ripening chambers."),
    S(1, 2, "Biology", "Which part of the human ear helps the body keep its balance?",
      ["Semicircular canals", "Cochlea", "Eardrum", "Eustachian tube"],
      "The fluid-filled semicircular canals of the inner ear sense movement of the head. The cochlea is for hearing and the Eustachian tube balances air pressure."),
    S(1, 2, "Indian geography", "The Satpura range lies between which two rivers?",
      ["Narmada and Tapi", "Ganga and Yamuna", "Godavari and Krishna", "Mahanadi and Son"],
      "The Satpura range runs between the Narmada to the north and the Tapi to the south, both of which flow west into the Arabian Sea. The Vindhyas lie north of the Narmada."),
    S(1, 1, "Neighbouring countries", "Mount Everest lies on the border between Nepal and which country?",
      ["China", "Bhutan", "India", "Pakistan"],
      "Everest lies on the border of Nepal and the Tibet region of China. India's highest peak, Kangchenjunga, is on the Nepal and Sikkim border."),
    S(1, 2, "Economy", "NABARD was set up mainly to provide what?",
      ["Rural and farm credit", "Foreign trade finance", "Housing loans in cities", "Stock market regulation"],
      "NABARD (1982) is the apex body for agriculture and rural development finance. EXIM Bank finances foreign trade, the National Housing Bank housing, and SEBI regulates markets."),
    S(1, 1, "Physics", "What causes an echo?",
      ["Reflection of sound", "Refraction of sound", "Absorption of sound", "Dispersion of sound"],
      "An echo is sound reflected back from a large surface such as a cliff or wall. It is heard separately if it returns at least about 0.1 seconds after the original sound."),
    S(1, 2, "Biology", "Which of these diseases is caused by a virus?",
      ["Rabies", "Tuberculosis", "Typhoid", "Cholera"],
      "Rabies is caused by a virus spread by animal bites. Tuberculosis, typhoid and cholera are caused by bacteria."),
    S(1, 2, "Indian geography", "Vembanad Lake, with the Kuttanad backwaters on its southern side, is in which state?",
      ["Kerala", "Tamil Nadu", "Karnataka", "Goa"],
      "Vembanad, often called the longest lake in India, lies in Kerala between Kochi and Alappuzha. Kuttanad, the rice bowl of Kerala, farms land below sea level beside it."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Rivers", "The Rihand Dam, whose reservoir is the Govind Ballabh Pant Sagar, is in which state?",
      ["Uttar Pradesh", "Madhya Pradesh", "Bihar", "Jharkhand"],
      "The Rihand Dam is on the Rihand river in Sonbhadra district of Uttar Pradesh; its reservoir reaches into Madhya Pradesh. It is one of India's largest artificial lakes."),
    S(2, 1, "Agriculture", "What is sericulture?",
      ["Rearing silkworms", "Keeping honeybees", "Breeding fish", "Growing flowers"],
      "Sericulture is the rearing of silkworms to produce silk. Keeping bees is apiculture, breeding fish pisciculture and growing flowers floriculture."),
    S(2, 2, "Economy", "What does the Cash Reserve Ratio (CRR) require banks to do?",
      ["Keep a share of deposits with RBI", "Hold gold equal to their loans", "Buy government bonds for all loans", "Keep foreign currency reserves"],
      "CRR is the share of deposits a bank must keep as cash with the Reserve Bank. The share kept in liquid assets such as government securities is the SLR."),
    S(2, 1, "Physics", "What is the SI unit of luminous intensity?",
      ["Candela", "Lux", "Lumen", "Dioptre"],
      "The candela is the SI base unit of luminous intensity. The lumen measures luminous flux, the lux illuminance and the dioptre the power of a lens."),
    S(2, 1, "Chemistry", "Malic acid is found mainly in which fruit?",
      ["Apples", "Lemons", "Tamarind", "Grapes"],
      "Malic acid gives apples their sharp taste. Lemons are rich in citric acid, and tamarind and grapes in tartaric acid."),
    S(2, 2, "Biology", "Which white blood cells produce antibodies?",
      ["Lymphocytes", "Neutrophils", "Eosinophils", "Basophils"],
      "B-lymphocytes make antibodies that mark germs for destruction. Neutrophils engulf bacteria, eosinophils act against parasites and in allergies, and basophils release histamine."),
    S(2, 2, "Indian geography", "Which mountain pass connects Sikkim with Tibet?",
      ["Nathu La", "Zoji La", "Shipki La", "Bomdi La"],
      "Nathu La links Sikkim with Tibet. Zoji La links Srinagar and Leh, Shipki La is in Himachal Pradesh and Bomdi La in Arunachal Pradesh."),
    S(2, 2, "Rivers", "By what name is the Brahmaputra known in Tibet?",
      ["Tsangpo", "Jamuna", "Padma", "Meghna"],
      "In Tibet the river is the Tsangpo (Yarlung Tsangpo). In Bangladesh it is called the Jamuna; the Padma is the Ganga there."),
    S(2, 2, "Economy", "In the Indian economy, what does 'disinvestment' mean?",
      ["Selling govt stake in PSUs", "Cutting the repo rate", "Raising import duties", "Printing more currency"],
      "Disinvestment is the government selling part or all of its shareholding in public sector undertakings, usually to raise money or bring in private management."),
    S(2, 1, "Physics", "What energy change takes place in an electric motor?",
      ["Electrical to mechanical", "Mechanical to electrical", "Chemical to electrical", "Heat to electrical"],
      "A motor uses electrical energy to produce motion. A generator does the reverse, turning mechanical energy into electrical energy."),
    S(2, 1, "Biology", "Which of these is found in a plant cell but not in an animal cell?",
      ["Cell wall", "Nucleus", "Mitochondria", "Ribosome"],
      "Plant cells have a cellulose cell wall (and chloroplasts) that animal cells lack. Both kinds have a nucleus, mitochondria and ribosomes."),
    S(2, 2, "Neighbouring countries", "Which of these countries is NOT a member of SAARC?",
      ["Myanmar", "Afghanistan", "Maldives", "Bhutan"],
      "SAARC has eight members: Afghanistan, Bangladesh, Bhutan, India, Maldives, Nepal, Pakistan and Sri Lanka. Myanmar is not a member."),
    # ---------- Drill only ----------
    S(0, 2, "Indian geography", "Saddle Peak, the highest point of the Andaman Islands, is on which island?",
      ["North Andaman", "Middle Andaman", "South Andaman", "Great Nicobar"],
      "Saddle Peak (about 732 m) is on North Andaman, near Diglipur. Port Blair, now Sri Vijaya Puram, is on South Andaman."),
    S(0, 2, "Earth science", "Which layer of the atmosphere reflects radio waves back to the Earth?",
      ["Ionosphere", "Troposphere", "Stratosphere", "Exosphere"],
      "The ionosphere holds charged particles that reflect some radio waves, which is how long-distance radio signals travel. Weather happens in the troposphere."),
    S(0, 2, "Economy", "Which Five-Year Plan was based on the Mahalanobis model, with its stress on heavy industry?",
      ["Second Plan", "First Plan", "Third Plan", "Fifth Plan"],
      "The Second Plan (1956 to 1961) followed P. C. Mahalanobis's model of rapid heavy industrialisation. The First Plan focused on agriculture."),
    S(0, 1, "Chemistry", "What does iron need in order to rust?",
      ["Oxygen and moisture", "Nitrogen and heat", "Carbon dioxide only", "Sunlight and salt"],
      "Rust (hydrated iron oxide) forms when iron reacts with oxygen in the presence of water. Salt speeds it up but is not required."),
]
